"""```
params = {
    'wte': (50257, 768),      # word token embeddings
    'wpe': (1024, 768),       # word positional embeddings
    'blocks': [               # 12 transformer blocks
        {
            'attn': {'c_attn': ..., 'c_proj': ...}, #'c_attn' --> combined linear layer(768, 3*768) that contains W_Q, W_K, W_V and 'c_proj' --> output projection (W_out) (768*768)applied after attention
            'mlp':  {'c_fc': ..., 'c_proj': ...}, #c_fc   : 768 -> 3072 and c_proj : 3072 -> 768
            'ln_1': {'g': ..., 'b': ...}, #g --> scale, b --> shift/bias
            'ln_2': {'g': ..., 'b': ...},
        },
        ...
    ],
    'g': ..., 'b': ...        # final LayerNorm
}
```
"""

def assign(custom_value, openai_value):
  with torch.no_grad():
    if not isinstance(openai_value, torch.Tensor):
      openai_value = torch.tensor(openai_value)
    openai_value = openai_value.to(dtype=custom_value.dtype, device=custom_value.device)
    custom_value.copy_(openai_value)  #the _ means in-place operation: change the existing tensor instead of making a new one.

def load_weights_into_gpt2(model, params):
  assign(model.tok_emb.weight, params['wte']) #Embedding layer has no bias and only weights
  assign(model.pos_emb.weight, params['wpe']) #Embedding layer has no bias and only weights

  for b in range(GPT_CONFIG_124M ['n_layers']):

    #Copy Attention weights into the model
    w_q, w_k, w_v = np.split(params['blocks'][b]['attn']['c_attn']['w'], 3, axis = -1)
    assign(model.trf_blocks[b].att.W_query.weight, w_q.T) #it mean we stored weights as (out_features, in_features) but openai stores weights as (in_features, out_features)
    assign(model.trf_blocks[b].att.W_key.weight, w_k.T)
    assign(model.trf_blocks[b].att.W_value.weight, w_v.T)

    b_q, b_k, b_v  = np.split(params['blocks'][b]['attn']['c_attn']['b'], 3, axis = -1)
    assign(model.trf_blocks[b].att.W_query.bias, b_q) #W_query is created using nn.Linear, so it has bias as well
    assign(model.trf_blocks[b].att.W_key.bias, b_k)  #W_key is created using nn.Linear, so it has bias as well
    assign(model.trf_blocks[b].att.W_value.bias, b_v) #W_value is created using nn.Linear, so it has bias as well

    assign(model.trf_blocks[b].att.W_out.weight, params['blocks'][b]['attn']['c_proj']['w'].T)
    assign(model.trf_blocks[b].att.W_out.bias, params['blocks'][b]['attn']['c_proj']['b']) #created using nn.Linear, so it has bias as well

    #Copy Feedforward weights into the model
    assign(model.trf_blocks[b].ff.layers[0].weight, params['blocks'][b]['mlp']['c_fc']['w'].T) #index here refers to module and not layer
    assign(model.trf_blocks[b].ff.layers[0].bias, params['blocks'][b]['mlp']['c_fc']['b']) #created using nn.Linear, so it has bias as well
    assign(model.trf_blocks[b].ff.layers[2].weight, params['blocks'][b]['mlp']['c_proj']['w'].T)
    assign(model.trf_blocks[b].ff.layers[2].bias, params['blocks'][b]['mlp']['c_proj']['b']) #created using nn.Linear, so it has bias as well

    #Copy Layer Norm weights into the model
    assign(model.trf_blocks[b].ln1.scale, params['blocks'][b]['ln_1']['g']) #scale already a parameter and not a module so no need to use .weight
    assign(model.trf_blocks[b].ln1.shift, params['blocks'][b]['ln_1']['b'])
    assign(model.trf_blocks[b].ln2.scale, params['blocks'][b]['ln_2']['g'])
    assign(model.trf_blocks[b].ln2.shift, params['blocks'][b]['ln_2']['b'])

  #Copy Final Layer Norm weights into the model
  assign(model.final_norm.scale, params['g'])
  assign(model.final_norm.shift, params['b'])
  assign(model.out_head.weight, params['wte'])

load_weights_into_gpt2(model, params)

#Passing a batch with only one input example
context = "Every effort moves you"
token_ids = torch.tensor(tokenizer.encode(context, allowed_special={'<|endoftext|>'}))
token_ids = token_ids.unsqueeze(0) #add batch dimension as model expects it
#print(token_ids.shape) #(1,4)

max_length = 25
top_k = 25
temperature = 1.4
context_size = GPT_CONFIG_124M["context_length"]

model.eval()
with torch.no_grad():
  for i in range(max_length):
    logits = model(token_ids[:, -context_size:]) #It ensures that number of tokens not greater than context_length otherwise we will run out of positional encodings
    logits = logits[:, -1, :] #select last row
    top_values, top_indices = torch.topk(logits, k=top_k)
    min_val = top_values[:, -1] #selects the minimum value from each example in batch
    logits = torch.where(
        condition = logits < min_val,
        input = torch.tensor(float('-inf')),
        other = logits
    )
    input = logits/temperature #select last row of logits
    probs = torch.softmax(input, dim = -1)
    next_token_id = torch.multinomial(probs, num_samples = 1)
    token_ids = torch.cat([token_ids, next_token_id], dim = -1)

tokens = tokenizer.decode(token_ids.squeeze(0).tolist())
print(tokens)